4	using chatai.Core.Config;
5	using Microsoft.Extensions.Logging;
6	
7	namespace chatai.Core.Service
8	{
9	    /// <summary>
10	    /// 呼叫 Gemini File Search REST API（https://ai.google.dev/gemini-api/docs/file-search）。
11	    /// 所有欄位命名都是實測 API 回應與錯誤訊息驗證過的，Google 這個 API 的 JSON 欄位命名不統一：
12	    /// FileSearchStore 資源用 camelCase（displayName），但 file_search 工具與 custom_metadata 用 snake_case。
13	    /// 放在 chatai.Core 是因為 chatai_backend（學生對話）跟 chatai_admin（管理端上傳共用文件）
14	    /// 都要用同一份邏輯、同一個 Gemini store，兩邊各自用自己的登入機制驗證身份後再呼叫。
15	    /// </summary>
16	    public class GeminiFileSearchService : IGeminiFileSearchService
17	    {
18	        /// <summary>
19	        /// 管理端上傳的共用文件，統一標記這個 user_id，查詢時所有使用者都看得到。
20	        /// </summary>
21	        public const string SharedUserId = "shared";
22	
23	        private readonly IHttpClientFactory _httpClientFactory;
24	        private readonly AppSettingConfig _appSetting;
25	        private readonly ILogger<GeminiFileSearchService> _logger;
26	
27	        private readonly SemaphoreSlim _storeLock = new(1, 1);
28	        private string? _cachedStoreName;
29	
30	        public GeminiFileSearchService(
31	            IHttpClientFactory httpClientFactory,
32	            AppSettingConfig appSetting,
33	            ILogger<GeminiFileSearchService> logger)
34	        {
35	            _httpClientFactory = httpClientFactory;
36	            _appSetting = appSetting;
37	            _logger = logger;
38	        }
39	
40	        private HttpClient CreateClient()
41	        {
42	            var client = _httpClientFactory.CreateClient("Gemini");
43	            client.DefaultRequestHeaders.Remove("x-goog-api-key");
44	            client.DefaultRequestHeaders.Add("x-goog-api-key", _appSetting.GeminiApiKey);
45	            return client;
46	        }
47	
48	        /// <summary>
49	        /// 依 displayName 找出已存在的 File Search Store，沒有就建立一個，結果快取在記憶體中（進程存活期間有效）。
50	        /// </summary>
51	        private async Task<string> GetOrCreateStoreAsync(HttpClient client)
52	        {
53	            if (_cachedStoreName != null)
54	                return _cachedStoreName;
55	
56	            await _storeLock.WaitAsync();
57	            try
58	            {
